<section class="account-page"><div class="account-heading"><div><p class="eyebrow">SATICI MERKEZİ</p><h1>Satış siparişleri</h1><p>Mağazanızdaki ürünlere ait son sipariş satırları.</p></div><a class="primary-link" href="<?= e(url('seller')) ?>">Satıcı paneli</a></div><div class="account-card responsive-table"><table><thead><tr><th>Sipariş</th><th>Ürün</th><th>Adet</th><th>Satır tutarı</th><th>Ödeme</th><th>Teslimat</th><th>Sipariş durumu</th><th>Tarih</th></tr></thead><tbody><?php foreach($sellerOrders as $o): ?><tr><td><?= e($o['order_no']) ?></td><td><?= e($o['product_name']) ?></td><td><?= (int)$o['quantity'] ?></td><td><?= number_format((float)$o['line_total'],2,',','.') ?> ₺</td><td><?= e($o['payment_status']) ?></td><td><?php $delivered=($o['delivery_type']??'manual')==='automatic'?(int)$o['automatic_delivered']:(int)$o['manual_delivered']; ?><?= $delivered ?>/<?= (int)$o['quantity'] ?></td><td><?= e($o['status']) ?></td><td><?= e(date('d.m.Y H:i',strtotime($o['created_at']))) ?></td></tr><?php endforeach; ?><?php if(!$sellerOrders): ?><tr><td colspan="8">Henüz mağazanıza ait sipariş bulunmuyor.</td></tr><?php endif; ?></tbody></table></div></section>